import sys

def longest_increasing_streak(prices):
    if not prices:
        return 0
    max_streak = 1
    current_streak = 1
    for i in range(1, len(prices)):
        if prices[i] > prices[i-1]:
            current_streak += 1
            max_streak = max(max_streak, current_streak)
        else:
            current_streak = 1
    return max_streak

def next_greater_elements(prices):
    n = len(prices)
    result = [-1] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and stack[-1] <= prices[i]:
            stack.pop()
        if stack:
            result[i] = stack[-1]
        stack.append(prices[i])
    return result

def max_profit_k_transactions(prices, k):
    if not prices or len(prices) < 2 or k == 0:
        return 0

    n = len(prices)

    if k >= n // 2:
        profit = 0
        for i in range(1, n):
            if prices[i] > prices[i-1]:
                profit += prices[i] - prices[i-1]
        return profit

    buy = [[0] * (k + 1) for _ in range(n)]
    sell = [[0] * (k + 1) for _ in range(n)]

    for i in range(1, n):
        for j in range(1, k + 1):
            buy[i][j] = max(buy[i-1][j], sell[i-1][j-1] - prices[i])
            sell[i][j] = max(sell[i-1][j], buy[i-1][j] + prices[i])

    return sell[n-1][k]

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    prices = list(map(int, data[1:n+1]))
    k = int(data[n+1])

    longest_streak = longest_increasing_streak(prices)
    max_profit = max_profit_k_transactions(prices, k)

    print(f"Longest Increasing Streak: {longest_streak}")
    print(f"Max Profit: {max_profit}")

if __name__ == "__main__":
    main()
